from rust_enum import Case, enum, Option # type: ignore

@enum
class Message:
    Quit = Case()
    Move = Case(x=int, y=int)
    Write = Case(text = str)
    ChangeColor = Case(r=int, g=int, b=int)


def process_message(msg: Message):
    match msg:
        case Message.Quit: print(f"Quit Appllication")

        case Message.Move(x=x,y=y): print(f"Move to position: ({x}, {y})")

        case Message.Write(text=t):  print(f"Writing: {t}")

        case Message.ChangeColor(r=r, g=g, b=b): print(f"Changing to color: ({r}, {g}, {b})")

        case _: print("Unknown Message")


def main() -> None:
    process_message(Message.Quit)
    process_message(Message.Move(x=10, y=20))
    process_message(Message.Write("hello there!"))
    process_message(Message.ChangeColor(r=255, g=0, b=255))

if __name__=="__main__":
    main()


