enum Message {
    Quit,
    Move {x: i32, y: i32},
    Write(String),
    ChangeColor(u8, u8, u8)
}

impl Message {
    fn process_message(&self) {
        match self {
            Message::Quit => println!("Quiting Appllication"),
            Message::Move {x, y} => println!("Moving to position: ({}, {})", x,y),
            Message::Write(text) => println!("Message: {}", text),
            Message::ChangeColor(r,g, b) => println!("change color to ({}, {}, {})", r,g,b)

        }
    }
}

fn main() {
    Message::Quit.process_message();
    Message::Move { x: 10, y: 20 }.process_message();
    Message::Write(String::from("Hello There! impl")).process_message();
    Message::ChangeColor(255, 0, 255).process_message();
}

